from __future__ import annotations

from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App


@pytest.mark.smoke
def test_typing_cl_lists_clear_chat_first_and_clear_all_third(app: App) -> None:
    # Enter runs the starred one: never "everything" by accident
    assert app.slash_list("/cl")[:4] == ["clear-chat*", "clear-variables", "clear-all", "close-tabs"]
    assert app.slash_list("/clear") == ["clear-chat*", "clear-variables", "clear-all"]
    assert app.slash_list("/clear-a") == ["clear-all*"]


def test_clear_all_clears_the_chat_and_the_variables(app: App) -> None:
    app.show("chat", "python", "variables")
    app.run_cell("kept_until_cleared = 41 + 1")
    app.page.wait_for_selector('.vars-table >> text="kept_until_cleared"')
    app.slash("/python")  # a row in the chat, to see it go (it hides the Python console)
    app.slash("/clear-all")
    app.page.wait_for_selector('.vars-table >> text="kept_until_cleared"', state="detached")
    rows = app.page.locator(".chat-items").inner_text()
    assert "/clear-all" in rows
    assert "a new conversation · cleared 1 variable" in rows
    assert "/python" not in rows  # the old chat's rows went
